// Trade Cars — Lead desde mensaje de Chatwoot. Desenvuelve el payload real de Chatwoot
// (el Webhook de n8n SIEMPRE lo entrega dentro de item.json.body, nunca al nivel raiz —
// mismo detalle que ya costo un bug real en el flujo del funnel, ver tradecars-funnel-guia.md)
// y decide si el mensaje ENTRANTE parece la notificacion de un formulario completado.
//
// Ajusta FRASES_FORMULARIO al texto real que use tu bot de Meta/Zapier al avisar por
// WhatsApp que alguien lleno el formulario.

const FRASES_FORMULARIO = [
  'completé el formulario',
  'complete el formulario',
  'obtener más información sobre el negocio',
  'obtener mas informacion sobre el negocio',
];

const salida = [];

for (const item of $input.all()) {
  const raw = item.json || {};
  const c = raw.body !== undefined && raw.body !== null ? raw.body : raw;

  const conv = c.conversation || c;
  const meta = conv.meta || c.meta || {};
  const sender = meta.sender || {};

  const messageType = String(c.message_type || conv.message_type || '').toLowerCase();
  const esEntrante = messageType === 'incoming' || messageType === '0';

  const contenido = String(c.content || conv.content || '').trim();
  const contenidoNorm = contenido.toLowerCase();
  const pareceFormulario = esEntrante && FRASES_FORMULARIO.some((f) => contenidoNorm.includes(f));

  const conversationId = conv.id !== undefined ? conv.id : null;
  const accountIdRaw = conv.account_id !== undefined ? conv.account_id
    : (c.account && c.account.id !== undefined ? c.account.id
    : (conv.messages && conv.messages[0] ? conv.messages[0].account_id : undefined));
  const inboxId = conv.inbox_id !== undefined ? conv.inbox_id : (c.inbox_id !== undefined ? c.inbox_id : null);

  salida.push({
    json: {
      _procesar: pareceFormulario,
      mensaje: contenido,
      telefono: sender.phone_number || '',
      nombre_chatwoot: sender.name || '',
      conversation_id: conversationId,
      account_id: accountIdRaw !== undefined && accountIdRaw !== null ? Number(accountIdRaw) : null,
      inbox_id: inboxId !== null ? Number(inboxId) : null,
    },
  });
}

return salida;

// Combina lo que ya se sabia por Chatwoot (telefono, nombre, conversation_id...) con lo que
// extrajo el AI Agent. Defensivo con la forma exacta de la respuesta: con el "Formato de
// salida" (Structured Output Parser) conectado, lo normal es que $json.output YA sea el
// objeto {marca, modelo, ...} listo. Sin parser, o en otras versiones de n8n, puede venir
// como texto (a veces con algo de charla alrededor) en .output, .text u otros campos — por
// eso se prueba en ese orden y, si es texto, se intenta JSON.parse y si no, se recorta el
// primer bloque {...} que aparezca.

const base = $('Leer mensaje').first().json;
const resp = $input.first().json || {};

function extraerJson(valor) {
  if (valor && typeof valor === 'object' && !Array.isArray(valor)) return valor;
  if (typeof valor !== 'string') return null;
  try { return JSON.parse(valor); } catch {}
  const m = valor.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch {} }
  return null;
}

const candidatos = [
  resp.output,
  resp.text,
  resp,
  resp.message && resp.message.content,
  resp.content,
  resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content,
];

let campos = null;
for (const c of candidatos) {
  campos = extraerJson(c);
  if (campos) break;
}
campos = campos || {};

return [{
  json: {
    telefono: base.telefono,
    nombre_chatwoot: base.nombre_chatwoot,
    correo: campos.correo ?? null,
    marca: campos.marca ?? null,
    modelo: campos.modelo ?? null,
    anio: campos.anio ?? null,
    kilometraje: campos.kilometraje ?? null,
    placa: campos.placa ?? null,
    distrito: campos.distrito ?? null,
    mensaje_original: base.mensaje,
    conversation_id: base.conversation_id,
    account_id: base.account_id,
    inbox_id: base.inbox_id,
  },
}];
